/**
 * Test-only global middleware: every response of a `vaulter.v1.*` route is checked against
 * openapi/vaulter-v1.yaml after the response is built, and the test fails with the list of
 * violations. Routes a test registers itself under `vaulter.v1.__probe*` are fixtures of the
 * HTTP kernel, not API surface, and stay outside the contract.
 */
final class ValidateOpenApiResponses
{
    public const string PREFIX = 'vaulter.v1.';

    private const string PROBE = 'vaulter.v1.__probe';

    public function handle(Request $request, Closure $next): Response
    {
        return $next($request);
    }

    public function terminate(Request $request, Response $response): void
    {
        $name = (string) $request->route()?->getName();
        if (!str_starts_with($name, self::PREFIX) || str_starts_with($name, self::PROBE)) {
            return;
