$mw = new ValidateOpenApiResponses();
function runMw(ValidateOpenApiResponses $mw, string $name, int $status, array $headers, string $body, bool $stream = false, string $method = 'GET'): string {
    $request = Request::create('/x', $method);
    $route = new Route([$method], '/x', static fn () => null);
    $route->name($name);
    $request->setRouteResolver(static fn () => $route);
    if ($stream) {
        $response = new StreamedResponse(static function () use ($body): void { echo $body; }, $status, $headers);
    } else {
        $response = new JsonResponse(json_decode($body, true), $status, $headers);
        // JsonResponse overwrites content-type; set after
        foreach ($headers as $k => $val) {
            $response->headers->set($k, $val);
        }
    }
    try {
        $mw->terminate($request, $response);
        return 'NO THROW';
    } catch (AssertionFailedError $e) {
        return 'THREW: ' . strtok($e->getMessage(), "\n");
    }
}

